from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import window
l=Lesson('Asymétrie ou déformation du visage')
l.add('Une asymétrie du visage peut traduire une différence ancienne, une faiblesse motrice ou une modification des volumes. Les {distinctions initiales} évitent de confondre paralysie, gonflement et déformation osseuse. L’apparition récente et les fonctions menacées déterminent la priorité.',
 paras('Observer le visage au repos, pendant la mimique spontanée et lors de gestes demandés. Une asymétrie visible n’est pas nécessairement un déficit moteur ; une photo antérieure peut aider à reconnaître un état ancien, avec l’accord du patient.', 'Une parésie réduit le mouvement, une paralysie l’abolit. Un œdème, une masse ou une fracture modifient les contours et peuvent limiter mécaniquement le mouvement. Plusieurs mécanismes peuvent coexister, notamment après un traumatisme ou devant une tumeur parotidienne.')+
 table(['Mécanisme','Question','Orientation'],[['Déficit moteur.','Le front, l’œil et la bouche bougent-ils de manière comparable ?','Localisation neurologique, puis recherche de la cause.'],['Augmentation de volume.','Douleur, rougeur, prurit, masse ou gonflement de la langue ?','Infection, tumeur ou angioœdème selon le contexte.'],['Déformation osseuse ou développementale.','Traumatisme, occlusion modifiée, anomalie ancienne ou croissance asymétrique ?','Bilan maxillofacial et fonctionnel.'],['Différence ancienne sans déficit nouveau.','Existe-t-elle sur les anciennes images et reste-t-elle stable ?','Évaluer le retentissement sans fabriquer une urgence neurologique.']]),(2,3,5,6,8,9))
l.add('La fréquence des causes dépend de l’âge, du mode d’apparition et du contexte. Les {repères épidémiologiques} ne permettent pas d’établir une prévalence suisse unique de toutes les asymétries faciales. Les dix diagnostics retenus sont organisés pour le raisonnement clinique.',
 paras('Le protocole HUG 2023 attribue environ 50 à 70 % des paralysies faciales périphériques à une forme idiopathique. Ce pourcentage concerne ce sous-groupe et ne décrit pas toutes les déformations du visage, ni une incidence annuelle suisse.', 'Une tuméfaction douloureuse liée à une dent, une déformation après choc et une anomalie congénitale ne partagent pas le même dénominateur. Le CHUV précise que les tumeurs salivaires bénignes sont plus fréquentes que les malignes, mais une masse individuelle doit être caractérisée.', 'L’âge et le terrain modifient les hypothèses : anomalies de développement et croissance chez l’enfant, causes vasculaires selon les facteurs de risque, infections selon les expositions. Aucun rang numérique de la liste ne justifie de retarder une urgence.'),(1,3,5,7,9,10))
l.add('La symétrie dépend du squelette, des tissus mous et de leur commande motrice. Les {bases anatomiques indispensables} distinguent nerf facial, trijumeau et structures de l’orbite et de la bouche. Ces repères expliquent les signes associés.',
 paras('Le nerf facial commande les muscles de la mimique et la fermeture active des paupières. Son noyau se situe dans le pont ; le nerf traverse ensuite le rocher et la région parotidienne avant de se distribuer au visage. Une lésion du noyau ou du trajet nerveux peut donner une faiblesse de type périphérique.', 'Les voies supranucléaires projettent vers les noyaux faciaux ; la commande supérieure est davantage bilatérale. Une atteinte centrale prédomine donc souvent sur le bas du visage, mais peut aussi toucher le haut. Une lésion pontique vasculaire peut produire un tableau périphérique : le front seul ne tranche pas toute suspicion d’AVC.', 'Le trijumeau assure l’essentiel de la sensibilité faciale ; sa branche mandibulaire commande les muscles masticateurs. Le facial traverse la parotide pour la mimique mais n’en assure pas la commande sécrétoire. Un œil qui ne ferme pas expose la cornée ; une fracture orbitaire ou une infection peut menacer le globe par un autre mécanisme.', 'Les espaces cellulaires de la face communiquent avec des régions cervicales profondes. Une infection dentaire peut donc dépasser sa porte d’entrée. Un œdème de la langue ou du pharynx peut compromettre la respiration même si l’asymétrie externe paraît limitée.')+
 table(['Structure','Fonction','Signe orientant'],[['Facial.','Mimique et fermeture palpébrale.','Front, sourire et occlusion oculaire faibles.'],['Trijumeau.','Sensibilité, mastication pour sa branche mandibulaire.','Hypoesthésie joue/menton ou trouble masticatoire.'],['Mandibule et arcades dentaires.','Occlusion et appui masticatoire.','Malocclusion après traumatisme.'],['Zygoma et orbite.','Relief de la pommette et protection oculaire.','Déformation, diplopie ou déplacement du globe.'],['Parotide et tissus mous.','Volume local, proximité du facial.','Masse avec ou sans déficit de mimique.']]),(2,3,5,6,7,8))
l.add('Le tri recherche d’abord une menace respiratoire, un déficit neurologique aigu ou une atteinte oculaire grave. Les {situations à exclure en priorité} guident l’orientation avant le classement étiologique. L’importance esthétique de la déformation ne mesure pas sa gravité.',
 table(['Priorité','Signaux','Conduite'],[['🚩 E1 — Voies aériennes ou anaphylaxie.','Langue/pharynx gonflés, stridor, dyspnée, collapsus ou aggravation rapide.','Urgence et équipe capable de sécuriser les voies aériennes ; traitement adapté au mécanisme.'],['🚩 E2 — AVC ou autre atteinte neurologique aiguë.','Déficit soudain, trouble du langage, faiblesse d’un membre, diplopie ou déséquilibre.','144 et filière neurovasculaire ; préciser heure de début ou dernière fois sans symptôme.'],['🚩 E3 — Infection profonde.','Plancher buccal gonflé, trismus marqué, dysphagie, dyspnée ou altération générale.','Évaluation hospitalière urgente, contrôle de la source et de l’extension.'],['🚩 E4 — Menace oculaire.','Baisse visuelle, douleur importante, atteinte orbitaire ou cornée exposée symptomatique.','Évaluation ophtalmologique urgente selon le tableau ; ne pas réduire le problème à la mimique.'],['🚩 E5 — Traumatisme complexe.','Hémorragie, trouble de conscience, lésion cervicale possible, malocclusion ou mobilité anormale.','Prise en charge du traumatisme et des fonctions vitales avant réparation du relief.'],['🚩 E6 — Tumeur ou paralysie atypique.','Masse avec déficit facial, progression, récidive, bilatéralité ou plusieurs nerfs atteints.','Bilan spécialisé accéléré ; ne pas conclure automatiquement à Bell.']])+comparison(),(1,2,3,5,6,7,8,9,10,15))
l.add('L’anamnèse précise l’apparition, les signes associés et les expositions. Les {questions discriminantes} différencient un problème moteur d’une modification de volume ou de structure. Une asymétrie transitoire d’apparition brutale reste potentiellement urgente.',
 table(['Question','Raison','Conséquence'],[['Quand le visage était-il normal pour la dernière fois ?','Un début soudain suggère notamment une cause vasculaire.','Ne pas attendre l’évolution pour activer la filière urgente.'],['Œil difficile à fermer, douleur ou baisse de vision ?','Exposition cornéenne ou atteinte oculaire associée.','Évaluer la protection et l’œil lui-même.'],['Otalgie, vésicules, baisse auditive ou vertige ?','Zona otique ou autre cause otologique.','Otoscopie et examen spécialisé.'],['Tique, érythème migrant, douleurs radiculaires ou méningées ?','Probabilité de neuroborréliose à apprécier.','Examens ciblés, sans interpréter une sérologie seule.'],['Dent douloureuse, soin récent, trismus ou déglutition difficile ?','Porte d’entrée odontogène et extension possible.','Bilan dentaire et gravité cervicale.'],['Choc, perte dentaire ou contacts dentaires modifiés ?','Fracture ou lésion dentaire.','Examen maxillofacial et oculaire adapté.'],['Médicament récent ou ancien, urticaire, épisodes familiaux de gonflement ?','Angioœdème mastocytaire ou bradykinique possible.','Rechercher notamment IEC, mécanisme et menace respiratoire.'],['Masse persistante, progression ou anomalie depuis l’enfance ?','Cause tumorale ou développementale.','Bilan anatomique et fonctionnel adapté.']]),(1,2,3,6,7,8,9,10,13))
l.add('L’examen compare repos, mouvements volontaires et fonctions associées. Les {gestes ciblés} incluent l’œil, l’oreille, la bouche, l’occlusion et l’examen neurologique. Une tuméfaction peut masquer un déficit ou empêcher mécaniquement un mouvement.',
 table(['Geste','Recherche','Interprétation'],[['Lever les sourcils, fermer doucement puis fermement les yeux, montrer les dents et gonfler les joues.','Répartition et intensité du déficit.','Localiser avec l’ensemble neurologique ; aucune manœuvre isolée n’exclut un AVC.'],['Évaluer fermeture palpébrale, symptômes et vision.','Lagophtalmie, exposition ou autre lésion oculaire.','Protection et avis selon les constatations.'],['Examen neurologique complet adapté.','Langage, membres, sensibilité, coordination, autres nerfs crâniens.','Déficit associé atypique pour Bell isolé.'],['Otoscopie et inspection du pavillon.','Vésicules, otite, écoulement, traumatisme.','Cause otologique ou zostérienne.'],['Inspection de la bouche et du plancher, dents et occlusion.','Foyer dentaire, collection, gonflement ou malocclusion.','Différencier infection et traumatisme ; rechercher extension profonde.'],['Palpation comparative des reliefs et des régions salivaires.','Marche osseuse, douleur, masse, adénopathie.','Imagerie et avis orientés.'],['Examen des anomalies anciennes.','Oreilles, mandibule, audition, alimentation et respiration.','Bilan développemental multidisciplinaire.']]),(1,2,3,5,6,7,9))
l.add('L’{approche syndromique} organise les signes avant de nommer une maladie. Les mécanismes peuvent se combiner. Une localisation présumée reste à confronter à l’évolution.',
 table(['Syndrome','Signes fonctionnels','Signes physiques'],[['7.1 — Déficit supranucléaire.','Trouble du sourire, parfois parole ou membre associé.','Prédominance inférieure, avec atteinte supérieure parfois possible.'],['7.2 — Déficit facial de type périphérique.','Fermeture oculaire difficile, fuite labiale, parfois goût ou audition modifiés.','Atteinte supérieure et inférieure du même côté.'],['7.3 — Tuméfaction inflammatoire.','Douleur, trismus, gêne alimentaire ou fièvre.','Gonflement, foyer dentaire ou autre porte d’entrée.'],['7.4 — Œdème transitoire.','Tension des lèvres/du visage, parfois gêne pharyngée.','Œdème avec ou sans urticaire ; rechercher la langue.'],['7.5 — Déformation traumatique.','Douleur, diplopie, malocclusion ou hypoesthésie.','Relief modifié, lésion dentaire ou mobilité osseuse anormale.'],['7.6 — Masse progressive.','Gêne locale parfois peu douloureuse.','Masse salivaire ou autre, parfois déficit facial associé.'],['7.7 — Anomalie développementale.','Difficultés auditives, alimentaires ou respiratoires possibles.','Hypoplasie et anomalies auriculaires ou squelettiques.']]),(1,2,3,6,7,8,9))
l.add('Le diagnostic positif identifie d’abord le mécanisme puis sa cause. Les {critères et pièges de confirmation} empêchent de nommer une paralysie de Bell ou une tumeur sans bilan adapté. Une asymétrie isolée n’a pas de test universel.',
 paras('Bell est un diagnostic d’élimination devant une faiblesse faciale de type périphérique, rapidement installée, sans autre cause mise en évidence au bilan adapté. Bilatéralité, progression inhabituelle, récidive, autre nerf atteint ou masse imposent de reconsidérer ce diagnostic.', 'Une suspicion d’AVC repose sur la clinique et l’imagerie appropriée ; une TDM initiale sans signe d’ischémie ne suffit pas à l’écarter. Une neuroborréliose requiert une concordance clinique et biologique ; une sérologie sanguine positive seule ne démontre pas une atteinte neurologique active.', 'Une fracture est caractérisée par l’examen et l’imagerie ; une masse parotidienne demande une démarche anatomique et tissulaire planifiée. Une microsomie est évaluée dans son ensemble clinique et fonctionnel, sans prétendre qu’un critère unique existe pour toutes les formes.'),(1,2,3,6,9,10,11,13,14))
l.add('Les explorations répondent à une hypothèse et à un degré d’urgence. Les {quatre niveaux du bilan} évitent une batterie identique devant toute asymétrie. Un examen de confirmation ne doit pas retarder la protection d’une fonction menacée.',
 paras('9.a — Il n’existe pas de référence unique : examen neurologique pour le déficit, imagerie pour l’AVC ou la fracture, prélèvement planifié pour une masse, bilan clinique et biologique pour l’infection ou l’angioœdème.', '9.b — Première intention : examen ciblé et tri. Une suspicion vasculaire conduit à l’imagerie cérébrale/vasculaire urgente ; une fracture ou infection profonde à une imagerie adaptée. Une masse salivaire relève d’un parcours spécialisé.', '9.c — Adapter l’examen à l’âge, au terrain et à la tolérance. Une suspicion de paralysie de Bell n’impose pas le même bilan partout : les recommandations HUG et DGN diffèrent notamment sur sérologies et ponction lombaire. La présentation atypique et les signes méningés renforcent l’indication d’une exploration neurologique.', '9.d — Imagerie du trajet facial, électrophysiologie, bilan du LCR, cytoponction ou autres prélèvements répondent à des questions précises. Pour un angioœdème héréditaire suspecté, la quantité et la fonction du C1-inhibiteur sont centrales ; le C4 seul ne suffit pas.')+
 table(['Question','Examen utile','Limite'],[['Atteinte vasculaire ?','TDM/IRM et exploration vasculaire selon filière.','Un seul signe frontal ou une TDM précoce peu contributive n’exclut pas tout AVC.'],['Fracture ou extension d’une infection ?','Imagerie maxillofaciale adaptée, avec contraste selon la question infectieuse.','Ne pas retarder une menace respiratoire ou oculaire.'],['Cause de paralysie atypique ?','Examen spécialisé, imagerie, biologie/LCR selon contexte.','Ne pas étiqueter idiopathique un bilan incomplet.'],['Masse parotidienne ?','Imagerie et prélèvement planifiés.','Éviter un geste ouvert non coordonné au parcours chirurgical.']]),(1,2,3,6,7,8,11,12,13,14))
l.add('L’{arbre décisionnel} sépare urgence et caractérisation progressive. Le patient est réévalué si l’évolution ne correspond pas à l’hypothèse initiale. La comparaison avec l’état antérieur reste utile sans retarder les soins urgents.',
 steps('Langue/pharynx gonflés, dyspnée ou collapsus → urgence respiratoire et traitement du mécanisme, avec recherche d’anaphylaxie.', 'Déficit soudain ou autre signe neurologique → 144 et filière AVC, même si les signes ont régressé.', 'Douleur, trismus ou foyer dentaire avec signes profonds → évaluer l’extension infectieuse et contrôler la source.', 'Traumatisme → sécuriser les fonctions, puis examiner occlusion, yeux, nerfs et squelette.', 'Faiblesse faciale isolée → protéger l’œil, examiner oreille et neurologie, rechercher signes atypiques et causes ciblées avant de retenir Bell.', 'Masse persistante → bilan spécialisé anatomique et tissulaire.', 'Anomalie ancienne ou développementale → évaluer audition, alimentation, respiration, occlusion et besoins du patient dans un parcours coordonné.'),(1,2,3,5,6,7,8,9,10))
adrenaline=window(l,20)
l.add('La prise en charge protège les fonctions avant de corriger l’aspect du visage. Les {objectifs et traitements orientés} dépendent de la cause confirmée ou fortement suspectée. Les médicaments ne sont pas interchangeables entre les mécanismes.',
 paras('11.A — Préserver respiration, cerveau, vision, déglutition et communication ; soulager la douleur et traiter la cause. Reconnaître le retentissement psychosocial sans réduire la demande à une question esthétique.', '11.B — Une anaphylaxie nécessite notamment de l’adrénaline intramusculaire selon le protocole d’urgence ; les antihistaminiques ne remplacent pas ce traitement. Un angioœdème bradykinique appelle une stratégie différente et une expertise adaptée, sans retarder la sécurisation des voies aériennes.', 'Une suspicion d’AVC active la filière spécialisée pour imagerie et éventuelle reperfusion selon éligibilité. Il ne faut pas exclure toute possibilité de traitement sur un délai isolé : certaines sélections dépendent de l’imagerie. Les médicaments antithrombotiques ne sont pas administrés à l’aveugle devant une asymétrie non caractérisée.', 'Une faiblesse palpébrale impose une protection cornéenne adaptée, lubrification et fermeture correctement enseignée. Le traitement précoce de Bell repose habituellement sur des corticoïdes après évaluation ; cette stratégie ne doit pas être transposée à une neuroborréliose probable ou confirmée, pour laquelle la DGN déconseille les corticoïdes additionnels aux antibiotiques.', 'Une cellulite peut nécessiter antibiothérapie, drainage et traitement de la dent causale. Les fractures sont traitées selon stabilité, occlusion et fonctions atteintes. Les masses et anomalies développementales relèvent d’une stratégie spécialisée, avec prise en compte de la croissance et du nerf facial.', '11.C — Suivre les résultats des examens prescrits, la récupération motrice, la fermeture oculaire et les signes d’extension. Une aggravation, une nouvelle douleur oculaire ou un déficit neurologique nouveau nécessite une réévaluation rapide.', '11.D — Le retour ambulatoire suppose l’absence de menace immédiate, des consignes compréhensibles, une protection oculaire maîtrisée si nécessaire et un suivi réellement organisé. Prévoir rééducation, soins dentaires, soutien psychosocial et adaptations selon le handicap. Les posologies sont rattachées au produit et à l’indication dans les fiches correspondantes après vérification suisse.')+paras(adrenaline),(1,2,4,5,7,8,9,11,12,13,14,15,20))
l.add('La prévention dépend de la cause et ne garantit pas une symétrie parfaite. Les {mesures aux trois niveaux} visent surtout les complications évitables. L’éducation accompagne la prise en charge fonctionnelle.',
 paras('Primaire : prévention des facteurs vasculaires, protection lors des activités à risque de traumatisme et santé buccodentaire. L’exposition aux tiques et les médicaments à risque de gonflement sont abordés selon le contexte, sans attribuer toutes les asymétries à une même cause.', 'Secondaire : reconnaître les signes d’AVC même transitoires, examiner un déficit facial atypique, une masse persistante ou une infection qui s’étend. Une anomalie développementale demande un repérage des fonctions auditives, alimentaires et respiratoires.', 'Tertiaire : prévenir lésions cornéennes, séquelles motrices et complications après traitement. Une rééducation adaptée et un soutien psychosocial peuvent améliorer l’autonomie et la communication ; les objectifs sont définis avec le patient.'),(1,2,5,7,8,9,10))
l.add('Distinguer faiblesse motrice, gonflement et déformation osseuse. Le front seul n’exclut pas un AVC et un œil qui ne ferme pas doit être protégé. Une infection profonde ou un œdème lingual peut menacer les voies aériennes. Une masse ou une paralysie atypique exige un bilan spécifique.',refs=(1,2,3,7,8,10))
l.quiz([
('Une asymétrie visible prouve-t-elle une paralysie ?','Non : elle peut être constitutionnelle, osseuse, œdémateuse ou liée à une masse.'),
('Une atteinte du front exclut-elle un AVC ?','Non : des atteintes centrales supérieures existent et une lésion pontique peut donner une sémiologie périphérique.'),
('Un déficit facial disparu en quelques minutes peut-il être urgent ?','Oui : une suspicion d’accident ischémique transitoire nécessite une évaluation urgente.'),
('Le nerf facial assure-t-il toute la sensibilité du visage ?','Non : l’essentiel de cette sensibilité dépend du trijumeau.'),
('Pourquoi examiner la fermeture palpébrale ?','Une fermeture insuffisante expose la cornée et nécessite une protection adaptée.'),
('Une otalgie avec vésicules change-t-elle le diagnostic présumé de Bell ?','Oui : elle oriente notamment vers une paralysie zostérienne.'),
('Une sérologie Lyme positive suffit-elle à une neuroborréliose ?','Non : la clinique et les examens appropriés doivent être concordants.'),
('Peut-on appliquer automatiquement le traitement de Bell à Lyme ?','Non : les recommandations sur les corticoïdes diffèrent pour une neuroborréliose probable ou confirmée.'),
('Quelle signification a une occlusion dentaire modifiée après choc ?','Elle suggère une lésion des structures maxillomandibulaires à rechercher.'),
('Une joue gonflée après douleur dentaire est-elle toujours bénigne ?','Non : trismus, plancher gonflé, dysphagie ou dyspnée peuvent annoncer une extension grave.'),
('Une masse parotidienne indolore peut-elle nécessiter un bilan ?','Oui : l’absence de douleur ne permet pas de conclure à la bénignité.'),
('Tout angioœdème relève-t-il des seuls antihistaminiques ?','Non : anaphylaxie, obstruction et mécanisme bradykinique demandent des conduites distinctes.'),
('Une anomalie congénitale est-elle seulement esthétique ?','Non : audition, alimentation, respiration et occlusion peuvent être concernées.'),
('Le chiffre de Bell parmi les paralysies décrit-il toutes les déformations faciales ?','Non : les populations et les dénominateurs sont différents.')],(1,2,3,6,7,8,9,10,13))
l.write()
